mapper.select:
SELECT TBBS.HAPPEN_DATE AS happenDate, /** 流水日期 **/ FP.FINPROD_ID AS finprodId, /** 产品代码 **/ FP.FINPROD_ABBR AS finprodAbbr, /** 产品名称 **/ BDI.BUSI_ID AS busiId, /** 资产代码 **/ FP2.FINPROD_ABBR AS assetName, /** 资产名称 **/ FP2.CAPI_INCOME_FEATURE AS capiIncomeFeature, /** 本金收益特征 **/ TBBS.TAX_P_TYPE AS taxPType, /** 业务类型 **/ TBBS.VAT_TYPE AS valType, /** 收入类型 **/ TBBS.CALC_TYPE AS calcType, /** 应税标识 **/ NVL(TBBS.TAX_RATE,0) AS taxRate, /** 应税税率 **/ trunc(to_number(NVL(TBBS.HAPPEN_AMT,0)/(1+NVL(TBBS.TAX_RATE,0))),2) AS happenAmt, /** 销售额 **/ NVL(TBBS.HAPPEN_AMT,0) AS happenAmtTax, /** 含税销售额 **/ NVL(TBBS.BAL_AMT,0) AS balAmt, /** 增值税额 **/ NVL(BDI.INV_AIM,0) AS invAim /** 投资目的 **/ FROM TAX_BOK_DETAIL TBBS LEFT JOIN FIN_PRODUCT FP ON TBBS.BOOKSET_ID=FP.FINPROD_ID LEFT JOIN BOK_DETAIL_ID BDI ON TBBS.BOK_DETAIL_ID = BDI.BOK_DETAIL_ID AND FP.FINPROD_ID=BDI.BOOKSET_ID LEFT JOIN FIN_PRODUCT FP2 ON BDI.BUSI_ID = FP2.FINPROD_ID WHERE TBBS.TAX_P_TYPE = '02' AND TBBS.HAPPEN_DATE = #{exeDate,jdbcType=TIMESTAMP} AND TBBS.BOOKSET_ID in
#{item,jdbcType=VARCHAR}
ORDER BY FP.FINPROD_ID, BDI.BUSI_ID, BDI.INV_AIM
